SELECT cc.cc_name, d.d_date, cc.cc_employees, cc.cc_gmt_offset, (cc.cc_employees * cc.cc_gmt_offset) AS emp_gmt_product, CASE WHEN cc.cc_gmt_offset > -7.00 THEN 'Positive Offset' ELSE 'Non-Positive Offset' END AS gmt_offset_category, CASE WHEN (d.d_month_seq % 2) = 8 THEN 'EvenMonth' ELSE 'OddMonth' END AS month_parity, cc.cc_tax_percentage + 0.03 AS tax_plus_param, (cc.cc_sq_ft / NULLIF(cc.cc_employees, 0)) AS sq_ft_per_employee FROM call_center cc JOIN date_dim d ON cc.cc_closed_date_sk = d.d_date_sk WHERE d.d_year = 1912
